import { defineStore } from 'pinia';

export type TrRulesChangeKind = 'created' | 'undone';

export interface TrRulesChange {
  docType: string;
  ruleId: string;
  kind: TrRulesChangeKind;
}

// CORE-6103 — "the transformation rules of a doc type changed somewhere other
// than the rules list itself" (the settings-assistant chat created or undid a
// rule). The list page (TransformationRules/List.vue) watches `revision` and
// reloads when `lastChange.docType` is the doc type it shows. A counter rather
// than an event bus, so a list that mounts later simply loads fresh anyway and
// nothing needs unsubscribing.
export const useTrRulesSyncStore = defineStore('tr_rules_sync', {
  state: () => ({
    revision: 0,
    lastChange: null as TrRulesChange | null,
  }),

  actions: {
    notifyChanged(change: TrRulesChange) {
      this.lastChange = { ...change };
      this.revision += 1;
    },
  },
});
